"""
Auth router and auth-state helpers for XO Cowork API.
"""

import datetime
import os
import threading
from typing import Optional, Dict, Any

import httpx
from fastapi import APIRouter, HTTPException
from pydantic import BaseModel


# External Chat API base URL (xo-swarm-api or similar)
CHAT_API_BASE_URL = os.getenv("CHAT_API_BASE_URL", "https://api-swarm-beta.xo.builders")

# Clerk user API key (long-lived). When set, used as Bearer token for all chat API calls;
# no consume flow. When not set, auth uses XO_AUTH_SESSION_ID + XO_POLL_TOKEN and consume.
# Requires xo-swarm-api to verify Clerk API keys (Bearer ak_xxx).
XO_API_KEY = os.getenv("XO_API_KEY", "").strip() or None

# XO backend browser-auth endpoints (new flow)
XO_AUTH_START_PATH = os.getenv("XO_AUTH_START_PATH", "/auth/browser/start")
XO_AUTH_STATUS_PATH = os.getenv("XO_AUTH_STATUS_PATH", "/auth/browser/status")
XO_AUTH_CONSUME_PATH = os.getenv("XO_AUTH_CONSUME_PATH", "/auth/browser/consume")
XO_GET_USER_ID_PATH = os.getenv("XO_GET_USER_ID_PATH", "/get-user-id")

# HTTP client timeout settings
HTTP_TIMEOUT = httpx.Timeout(30.0, connect=10.0)


auth_lock = threading.Lock()
auth_state: Dict[str, Any] = {
    "access_token": None,
    "refresh_token": None,
    "expires_at": None,
    "user_id": None,
    "auth_session_id": None,
}


def set_auth_token(
    access_token: str,
    refresh_token: Optional[str] = None,
    expires_in: Optional[int] = None,
    user_id: Optional[str] = None,
    auth_session_id: Optional[str] = None,
) -> None:
    """Store active auth token for outbound requests to xo-swarm-api."""
    expires_at = None
    if expires_in:
        expires_at = (
            datetime.datetime.now(datetime.timezone.utc)
            + datetime.timedelta(seconds=expires_in)
        ).isoformat()
    with auth_lock:
        auth_state["access_token"] = access_token
        auth_state["refresh_token"] = refresh_token
        auth_state["expires_at"] = expires_at
        auth_state["user_id"] = user_id
        auth_state["auth_session_id"] = auth_session_id


def clear_auth_token() -> None:
    """Clear active auth token state."""
    with auth_lock:
        auth_state["access_token"] = None
        auth_state["refresh_token"] = None
        auth_state["expires_at"] = None
        auth_state["user_id"] = None
        auth_state["auth_session_id"] = None


def get_auth_token() -> Optional[str]:
    """
    Get active access token for outbound calls to xo-swarm-api.
    When XO_API_KEY is set it is used (no consume). Otherwise in-memory token from consume.
    """
    if XO_API_KEY:
        return XO_API_KEY
    with auth_lock:
        return auth_state.get("access_token")


def get_auth_state() -> Dict[str, Any]:
    """Return a safe auth state snapshot (without exposing token value)."""
    with auth_lock:
        token = auth_state.get("access_token")
    # When XO_API_KEY is set it is used for all requests; otherwise session token from consume.
    source = "api_key" if XO_API_KEY else ("session" if token else "none")
    effective_token = XO_API_KEY or token
    with auth_lock:
        return {
            "authenticated": bool(effective_token),
            "user_id": auth_state.get("user_id"),
            "expires_at": auth_state.get("expires_at"),
            "auth_session_id": auth_state.get("auth_session_id"),
            "token_source": source,
        }


class XOAuthStartRequest(BaseModel):
    """Start browser auth flow via xo-swarm-api."""

    scopes: Optional[str] = None
    client_reference: Optional[str] = None


class XOAuthConsumeRequest(BaseModel):
    """Consume completed browser auth flow."""

    auth_session_id: Optional[str] = None
    poll_token: Optional[str] = None


router = APIRouter(prefix="/xo-auth", tags=["auth"])


def resolve_consume_credentials(
    auth_session_id: Optional[str], poll_token: Optional[str]
) -> tuple[str, str]:
    """
    Resolve consume credentials with body-first, env-fallback strategy.
    """
    resolved_auth_session_id = (auth_session_id or "").strip() or os.getenv(
        "XO_AUTH_SESSION_ID", ""
    ).strip()
    resolved_poll_token = (poll_token or "").strip() or os.getenv(
        "XO_POLL_TOKEN", ""
    ).strip()
    if not resolved_auth_session_id or not resolved_poll_token:
        raise HTTPException(
            status_code=400,
            detail={
                "error": (
                    "Missing auth_session_id/poll_token. "
                    "Provide in request body or set XO_AUTH_SESSION_ID and XO_POLL_TOKEN."
                )
            },
        )
    return resolved_auth_session_id, resolved_poll_token


async def consume_auth_flow(auth_session_id: str, poll_token: str) -> Dict[str, Any]:
    """
    Call XO consume endpoint and store returned access token in-memory.
    """
    url = f"{CHAT_API_BASE_URL.rstrip('/')}{XO_AUTH_CONSUME_PATH}"
    payload = {"auth_session_id": auth_session_id, "poll_token": poll_token}
    try:
        async with httpx.AsyncClient(timeout=HTTP_TIMEOUT) as client:
            response = await client.post(url, json=payload)
        if response.status_code != 200:
            raise HTTPException(
                status_code=response.status_code,
                detail={"error": "Failed to consume auth flow", "upstream": response.text},
            )

        result = response.json()
        access_token = result.get("access_token")
        if not access_token:
            raise HTTPException(
                status_code=500, detail={"error": "No access token in consume response"}
            )

        set_auth_token(
            access_token=access_token,
            refresh_token=result.get("refresh_token"),
            expires_in=result.get("expires_in"),
            user_id=result.get("user_id"),
            auth_session_id=result.get("auth_session_id"),
        )
        return {
            "success": True,
            "message": "Authentication completed and token stored",
            "user_id": result.get("user_id"),
            "expires_in": result.get("expires_in"),
            "scope": result.get("scope"),
        }
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(
            status_code=500, detail={"error": f"Failed to consume auth flow: {str(e)}"}
        )


@router.post("/start")
async def xo_auth_start(data: XOAuthStartRequest):
    """
    Start XO backend browser auth flow.
    Returns authorize_url + auth_session_id + poll_token.
    """
    url = f"{CHAT_API_BASE_URL.rstrip('/')}{XO_AUTH_START_PATH}"
    payload = {
        "scopes": data.scopes,
        "client_reference": data.client_reference,
    }
    try:
        async with httpx.AsyncClient(timeout=HTTP_TIMEOUT) as client:
            response = await client.post(url, json=payload)
        if response.status_code != 200:
            raise HTTPException(
                status_code=response.status_code,
                detail={"error": "Failed to start auth flow", "upstream": response.text},
            )
        return response.json()
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(
            status_code=500, detail={"error": f"Failed to start auth flow: {str(e)}"}
        )


@router.get("/status/{auth_session_id}")
async def xo_auth_status(auth_session_id: str, poll_token: str):
    """Poll XO backend auth flow status."""
    url = f"{CHAT_API_BASE_URL.rstrip('/')}{XO_AUTH_STATUS_PATH}/{auth_session_id}"
    try:
        async with httpx.AsyncClient(timeout=HTTP_TIMEOUT) as client:
            response = await client.get(url, params={"poll_token": poll_token})
        if response.status_code != 200:
            raise HTTPException(
                status_code=response.status_code,
                detail={"error": "Failed to check auth status", "upstream": response.text},
            )
        return response.json()
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(
            status_code=500, detail={"error": f"Failed to check auth status: {str(e)}"}
        )


@router.post("/consume")
async def xo_auth_consume(data: XOAuthConsumeRequest):
    """
    Consume auth flow and store token in-memory for outgoing XO backend calls.

    Request body values take precedence. If missing, fallback to env:
    - XO_AUTH_SESSION_ID
    - XO_POLL_TOKEN
    """
    auth_session_id, poll_token = resolve_consume_credentials(
        data.auth_session_id, data.poll_token
    )
    return await consume_auth_flow(auth_session_id, poll_token)


@router.get("/whoami")
async def xo_auth_whoami():
    """
    Validate stored token against XO backend /get-user-id endpoint.
    """
    token = get_auth_token()
    if not token:
        raise HTTPException(
            status_code=401,
            detail={"error": "No stored access token. Complete /xo-auth flow first."},
        )

    url = f"{CHAT_API_BASE_URL.rstrip('/')}{XO_GET_USER_ID_PATH}"
    headers = {"Authorization": f"Bearer {token}"}
    try:
        async with httpx.AsyncClient(timeout=HTTP_TIMEOUT) as client:
            response = await client.get(url, headers=headers)
        if response.status_code != 200:
            raise HTTPException(
                status_code=response.status_code,
                detail={"error": "Token validation failed", "upstream": response.text},
            )
        data = response.json()
        with auth_lock:
            auth_state["user_id"] = data.get("user_id")
        return {"success": True, "user_id": data.get("user_id")}
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(
            status_code=500, detail={"error": f"Failed to validate token: {str(e)}"}
        )


@router.get("/state")
async def xo_auth_state():
    """Get current auth state (safe view)."""
    return get_auth_state()


@router.post("/logout")
async def xo_auth_logout():
    """Clear stored auth token state."""
    clear_auth_token()
    return {"success": True, "message": "Auth token cleared"}

"""
Configuration / provider / model-list endpoints.

Groups `/api/config/*` (api-key, providers, openclaw, openyak-account,
ollama, local, openai-subscription) and the per-agent model listing
(`/api/models`). Responses here shape what the UI sees in provider menus
and the settings screen.

Provider onboarding recipes now come from the active agent's manifest
(`config/agents/<agent>.json` → `providers.*`) instead of an inline dict,
so adding a provider (or swapping agents) is a config change.
"""

import asyncio
import os
from datetime import datetime, timezone
from pathlib import Path

from fastapi import APIRouter, Request
from fastapi.responses import JSONResponse

from services.cowork_agent.registry.agent_registry import get_agent, get_active_agent
from services.cowork_agent.helpers import _mask_sensitive
from services.cowork_agent.registry.agent_env import upsert_env_entry
from services.cowork_agent.project_layout import xo_projects_root
from services.cowork_agent.adapters.loader import try_load_capability

router = APIRouter()

_AGENT = get_active_agent()


async def _run_provider_provisioning(provider_id: str, argvs: list[list[str]]) -> None:
    """Run the active agent's CLI chain for a provider, appending output to
    its provisioning log.

    Argvs are pre-rendered from the manifest's command templates — no
    user input is interpolated, so `create_subprocess_exec` is safe.
    Chain aborts on the first non-zero exit so a broken `models set`
    doesn't leave later aliases pointing at nothing.
    """
    log_path = _AGENT.provisioning_log
    log_path.parent.mkdir(parents=True, exist_ok=True)
    ts = datetime.now(timezone.utc).isoformat()
    with log_path.open("a") as log:
        log.write(f"\n=== {ts} provisioning: {provider_id} ===\n")
        for argv in argvs:
            log.write(f"$ {' '.join(argv)}\n")
            log.flush()
            try:
                proc = await asyncio.create_subprocess_exec(
                    *argv,
                    cwd=str(_AGENT.cwd),
                    stdout=asyncio.subprocess.PIPE,
                    stderr=asyncio.subprocess.STDOUT,
                )
                stdout, _ = await proc.communicate()
                log.write(stdout.decode(errors="replace"))
                log.write(f"[exit {proc.returncode}]\n")
                if proc.returncode != 0:
                    log.write("[chain aborted]\n")
                    return
            except Exception as e:  # noqa: BLE001 — log every failure, keep going
                log.write(f"[exception] {e}\n[chain aborted]\n")
                return
        log.write("[chain ok]\n")


@router.post("/api/config/providers/{provider_id}/key")
async def save_provider_key(provider_id: str, request: Request):
    """Persist a provider API key and kick off the agent's CLI chain.

    Returns 200 as soon as the key is safely written to the agent's env
    file. The CLI chain runs in the background; its output is appended to
    the agent's provisioning log for later inspection.
    """
    recipe = _AGENT.providers.get(provider_id)
    if recipe is None:
        return JSONResponse(
            status_code=400,
            content={"detail": f"Unsupported provider: {provider_id}"},
        )

    try:
        body = await request.json()
    except Exception:
        return JSONResponse(status_code=400, content={"detail": "Invalid JSON body"})

    api_key = (body.get("api_key") or "").strip() if isinstance(body, dict) else ""
    if not api_key:
        return JSONResponse(status_code=400, content={"detail": "api_key is required"})

    try:
        upsert_env_entry(recipe["env_key"], api_key)
    except Exception as e:  # noqa: BLE001 — surface the real reason to the UI
        return JSONResponse(status_code=500, content={"detail": f"Failed to save key: {e}"})

    try:
        argvs = _AGENT.render_recipe_commands(recipe.get("commands") or [])
    except (KeyError, ValueError) as e:
        return JSONResponse(
            status_code=500,
            content={"detail": f"Invalid provider recipe for '{provider_id}': {e}"},
        )

    asyncio.create_task(_run_provider_provisioning(provider_id, argvs))

    return {"ok": True, "provider": provider_id, "provisioning": "started"}


# ── Model listing ────────────────────────────────────────────────────────────


@router.get("/api/models")
def list_models():
    """Return one model row per agent/profile under the active backend.

    Dispatch is resolved through the active agent's ``models`` capability
    (``adapters/<AGENT_NAME>/models.py`` → ``list_models()``): hermes scans
    ``~/.hermes/profiles/``; openclaw (and claude_code, which re-exports it)
    scans ``~/.openclaw/agents/``. No core code names a specific backend.
    """
    mod = try_load_capability("models")
    if mod is None or not hasattr(mod, "list_models"):
        return []
    return mod.list_models()


# ── /api/config/* routes ─────────────────────────────────────────────────────


@router.get("/api/config/api-key")
def config_api_key():
    return {"has_key": True, "provider": _AGENT.name}


@router.get("/api/config/providers")
def config_providers():
    return []


@router.get("/api/config/openai-subscription")
def openai_subscription():
    return {"is_connected": False, "email": "", "needs_reauth": False}


@router.get("/api/config/openyak-account")
def openyak_account():
    return {"linked": False}


@router.get("/api/config/ollama")
def ollama_config():
    return {"installed": False}


@router.get("/api/config/local")
def local_provider():
    return {"available": False}


@router.get("/api/config/agents/{name}")
def get_agent_config(name: str):
    """Unified per-agent config loader the FE Settings → Config tab calls.

    Returns ``{agent, config_file, config}`` where ``config`` is the parsed
    config file (json for openclaw, yaml for hermes) with sensitive values
    masked. The FE refresh button hits this route — without it both
    backends 404 and the panel hangs at "Failed to load configuration".

    Dispatch by manifest name so we don't accidentally re-anchor to the
    active default agent (same rule that protects the hermes-named routes).
    """
    try:
        manifest = get_agent(name)
    except (KeyError, ValueError):
        return JSONResponse(
            status_code=400,
            content={"detail": f"Unknown agent backend: {name}"},
        )

    config_path = manifest.config_file
    if not config_path.exists():
        return JSONResponse(
            status_code=404,
            content={"detail": f"{config_path.name} not found at {config_path}"},
        )

    suffix = config_path.suffix.lower()
    try:
        if suffix in (".yaml", ".yml"):
            import yaml
            raw = yaml.safe_load(config_path.read_text()) or {}
        else:
            import json as _json
            raw = _json.loads(config_path.read_text() or "{}")
    except (OSError, ValueError) as e:
        return JSONResponse(
            status_code=500,
            content={"detail": f"Failed to read {config_path}: {e}"},
        )

    if not isinstance(raw, dict):
        return JSONResponse(
            status_code=500,
            content={"detail": f"Unexpected top-level shape in {config_path.name}: {type(raw).__name__}"},
        )

    return {
        "agent": name,
        "config_file": str(config_path),
        "config": _mask_sensitive(raw),
    }


@router.get("/api/config/workspace")
def get_workspace_config():
    """
    Return workspace root paths for each agent backend.

    The unified ``xo-projects`` root (``XO_PROJECTS_ROOT`` env, default
    ``~/xo-projects``) is exposed under whichever backend is active so the
    new-project picker keeps working. We also surface each installed
    backend's native home so the frontend's
    ``agentNameForWorkspace(workspaceDirectory)`` lookup can recognize
    backend-specific paths like ``~/.openclaw/agents/<id>`` and route
    chats accordingly — without that, every chat falls back to the
    active backend's default agent regardless of which sidebar agent
    the user picked.

    Response shape:
      {
        "roots": {
           "<active_backend>": "/home/coder/xo-projects",
           "<backend>": "/home/coder/.<backend>",
           ...
        },
        "default": "<active_backend>"
      }
    """
    from services.cowork_agent.registry.agent_registry import _discover_manifests

    projects_root = str(xo_projects_root())
    default_backend = os.getenv("AGENT_NAME", _AGENT.name)

    # Start with the active backend rooted at xo-projects (legacy contract).
    roots: dict[str, str] = {default_backend: projects_root}

    # Add each installed backend's native home so the frontend can match
    # backend-specific paths (~/.openclaw/agents/<id>, ~/.hermes/profiles/<name>).
    for name, manifest in _discover_manifests().items():
        # Don't overwrite the active backend's xo-projects entry.
        roots.setdefault(name, str(manifest.home_dir))

    return {"roots": roots, "default": default_backend}

